VAR_INPUT
    enable : BOOL;
    values : ARRAY[1..8] OF INT;
    count  : INT;
    avgEnable : BOOL;
END_VAR
VAR_OUTPUT
    avgOut : REAL;
END_VAR
VAR
    lastAvg : REAL := 0.0;
    sum : DINT;
    i : INT;
    effectiveCount : INT;
END_VAR

// Body
IF enable AND avgEnable AND count > 0 THEN
    // Limit count to array size
    effectiveCount := count;
    IF effectiveCount > 8 THEN
        effectiveCount := 8;
    END_IF;

    // Compute sum using wider type
    sum := 0;
    FOR i := 1 TO effectiveCount DO
        sum := sum + values[i];
    END_FOR;

    // Compute average as REAL
    avgOut := DINT_TO_REAL(sum) / DINT_TO_REAL(effectiveCount);

    // Store for retention when not updating
    lastAvg := avgOut;
ELSE
    // Keep previous average
    avgOut := lastAvg;
END_IF;

END_FUNCTION_BLOCK

